from itertools import product
from collections import Counter
import heapq


def _ledger(data, revision_priority, tax_base, refund):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_priority == "sequence_first":
            order = (sequence, event.get("revision", 0), pos)
        else:
            order = (event.get("revision", 0), pos)
        if event_id not in chosen or order > chosen[event_id][0]:
            chosen[event_id] = (order, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(n, d=10000):
        return (n + d // 2) // d if half_up else n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if tax_base == "discounted" else raw
        total = net + rounded(base * event.get("tax_bp", 0))
        if refund and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_component_01():
    return lambda data: _ledger(data, "sequence_first", "discounted", True)


def _build_component_02():
    return lambda data: _ledger(data, "revision_first", "original", True)


def _build_component_03():
    return lambda data: _ledger(data, "sequence_first", "original", True)


def _build_component_04():
    return lambda data: _ledger(data, "revision_first", "discounted", True)


def _build_component_05():
    return lambda data: _ledger(data, "sequence_first", "discounted", True)


def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {name: {row["version"]: row for row in packages[name]} for name in names}
        choices = []
        for name in names:
            choices.append([-1] + sorted(rows[name]))

        for vector in product(*choices):
            installed = {name: version for name, version in zip(names, vector)
                         if version != -1}
            valid = True
            for name, bounds in data["roots"].items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, version in installed.items():
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
            if not valid:
                continue

            reachable = set()
            graph = {}
            pending = list(data["roots"])
            while pending and valid:
                name = pending.pop()
                if name in reachable:
                    continue
                version = installed.get(name)
                if version is None:
                    valid = False
                    break
                reachable.add(name)
                deps = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = installed.get(other)
                    if (other_version is None or not dep["min"] <= other_version <= dep["max"]):
                        valid = False
                        break
                    deps.append(other)
                    pending.append(other)
                graph[name] = deps
            if not valid or reachable != set(installed):
                continue

            visiting, visited = set(), set()
            def acyclic(name):
                if name in visiting:
                    return False
                if name in visited:
                    return True
                visiting.add(name)
                if any(not acyclic(other) for other in graph.get(name, [])):
                    return False
                visiting.remove(name)
                visited.add(name)
                return True

            if not all(acyclic(name) for name in reachable):
                continue
            return {"versions": installed}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        available = [job for job in jobs if job["id"] not in blocked]
        for selected in __import__("itertools").combinations(available, k):
            ids = {job["id"] for job in selected}
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in selected)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            intervals = sorted((job["start"], job["end"]) for job in selected)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue
            value = sum(job["value"] for job in selected)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids < best_ids)):
                best_value, best_ids = value, sorted_ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                for duration, left in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, left)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time,) + next_state)
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
